                marker = ('v', c, g[0][c])
                break

    axis, pos, marker_color = marker
    obj_color = next(x for row in g for x in row if x not in (bg, marker_color))
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == obj_color]

    if axis == 'h':
        # The marker is a boundary; insert an 8 line just beyond the object's far edge.
